#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE = 1000005;
const int MODULUS = 1000000007;

int sequence[MAX_SIZE];
bool visited_nodes[MAX_SIZE];
int p_value, k_value;

int main()
{
    cin >> p_value >> k_value;
    if (k_value == 0) {
        long long prod = 1;
        for (int i = 1; i < p_value; ++i) {
            prod = (prod * p_value) % MODULUS;
        }
        cout << prod << "\n";
        return 0;
    }
    for (int i = 1; i < p_value; ++i) {
        sequence[i] = (long long)k_value * i % p_value;
    }
    long long answer = 1;
    for (int start = 0; start < p_value; ++start) {
        if (!visited_nodes[start]) {
            int length = 0;
            int current = start;
            int tmp_product = 1;
            while (!visited_nodes[current]) {
                visited_nodes[current] = true;
                current = sequence[current];
                length++;
                tmp_product = (long long)tmp_product * k_value % p_value;
            }
            if (length == 1) {
                int factor = (k_value == 1) ? p_value : 1;
                answer = (answer * factor) % MODULUS;
            } else {
                assert(tmp_product == 1);
                answer = (answer * p_value) % MODULUS;
            }
        }
    }
    cout << answer << "\n";
}
